SOURCE tests/procedures/support/fixture.sql;
CALL bank_lab.sp_expect_ok(DATABASE(),'withdraw success','CALL {db}.sp_withdraw(@p3_a,1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)');
SET @p3_ok=(SELECT @p3_balance=499999 AND balance_after=@p3_balance AND transaction_type='Withdrawal' AND status='Completed' FROM Transactions WHERE transaction_id=@p3_tx);
CALL bank_lab.sp_assert_true(DATABASE(),'withdraw output and ledger',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_ok(DATABASE(),'withdraw Branch','CALL {db}.sp_withdraw(@p3_a,1,''Branch'',@p3_t1,NULL,NULL,@p3_tx,@p3_balance)');
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw amount 0','CALL {db}.sp_withdraw(@p3_a,0,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw amount -1','CALL {db}.sp_withdraw(@p3_a,-1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw amount NULL','CALL {db}.sp_withdraw(@p3_a,NULL,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw missing account','CALL {db}.sp_withdraw(-1,1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5002);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw insufficient funds','CALL {db}.sp_withdraw(@p3_a,999999,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5004);
SET @p3_amount=(SELECT balance-1000 FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_expect_ok(DATABASE(),'withdraw exact minimum boundary','CALL {db}.sp_withdraw(@p3_a,@p3_amount,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)');
SET @p3_ok=(SELECT balance=1000 FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_assert_true(DATABASE(),'withdraw retained minimum',@p3_ok,'Expected procedure contract');
SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw below minimum','CALL {db}.sp_withdraw(@p3_a,1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5004);
SET @p3_ok=(SELECT COUNT(*)=@p3_failed+1 FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_assert_true(DATABASE(),'withdraw exactly one Failed',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw wrong branch','CALL {db}.sp_withdraw(@p3_a,1,''Branch'',@p3_t2,NULL,NULL,@p3_tx,@p3_balance)',5010);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw non-branch employee','CALL {db}.sp_withdraw(@p3_a,1,''ATM'',@p3_t1,NULL,NULL,@p3_tx,@p3_balance)',5010);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw invalid channel','CALL {db}.sp_withdraw(@p3_a,1,''Other'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5018);
CALL sp_set_account_status(@p3_a,'Frozen',@p3_t1);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw Frozen','CALL {db}.sp_withdraw(@p3_a,1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5003);
CALL sp_set_account_status(@p3_a,'Active',@p3_t1);
INSERT INTO DB_User_Map(db_login,actor_type,employee_id) VALUES(USER(),'Employee',@p3_t1);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw spoofed employee','CALL {db}.sp_withdraw(@p3_a,1,''Branch'',@p3_t2,NULL,NULL,@p3_tx,@p3_balance)',5010);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL sp_close_account(@p3_a,NULL,1);
CALL bank_lab.sp_expect_error(DATABASE(),'withdraw Closed','CALL {db}.sp_withdraw(@p3_a,1,''Online'',NULL,NULL,NULL,@p3_tx,@p3_balance)',5003);
